/**
 * THH Club Membership — Discount & Role Management
 * Handles: role assignment, cart discounts, free shipping
 */

// Product IDs
if (!defined('THH_STARTER_ID')) define('THH_STARTER_ID', 49091);
if (!defined('THH_PRO_ID'))     define('THH_PRO_ID', 49092);
if (!defined('THH_ELITE_ID'))   define('THH_ELITE_ID', 49093);

$thh_tiers = [
    'starter' => ['discount' => 5,  'free_ship' => false, 'role' => 'thh_starter'],
    'pro'     => ['discount' => 10, 'free_ship' => true,  'role' => 'thh_pro'],
    'elite'   => ['discount' => 15, 'free_ship' => true,  'role' => 'thh_elite'],
];

// Register custom roles
add_action('init', function() {
    $cap = get_role('customer') ? get_role('customer')->capabilities : [];
    if (!get_role('thh_starter')) add_role('thh_starter', 'THH Club Starter', $cap);
    if (!get_role('thh_pro'))     add_role('thh_pro', 'THH Club Pro', $cap);
    if (!get_role('thh_elite'))   add_role('thh_elite', 'THH Club Elite', $cap);
});

// Get user membership tier
function thh_get_user_tier($user_id = null) {
    if (!$user_id) $user_id = get_current_user_id();
    if (!$user_id) return null;
    $user = get_userdata($user_id);
    if (!$user) return null;
    if (in_array('thh_elite', $user->roles))   return 'elite';
    if (in_array('thh_pro', $user->roles))     return 'pro';
    if (in_array('thh_starter', $user->roles)) return 'starter';
    return null;
}

// Get tier from product ID
function thh_get_tier_from_product($pid) {
    if ($pid == THH_STARTER_ID) return 'starter';
    if ($pid == THH_PRO_ID)     return 'pro';
    if ($pid == THH_ELITE_ID)   return 'elite';
    return null;
}

// Assign role helper
function thh_assign_membership_role($user_id, $tier) {
    global $thh_tiers;
    $user = get_userdata($user_id);
    if (!$user || !isset($thh_tiers[$tier])) return;

    // Remove all THH roles first
    $user->remove_role('thh_starter');
    $user->remove_role('thh_pro');
    $user->remove_role('thh_elite');

    // Assign new role
    $user->add_role($thh_tiers[$tier]['role']);
}

// Remove all THH roles
function thh_remove_membership_roles($user_id) {
    $user = get_userdata($user_id);
    if (!$user) return;
    $user->remove_role('thh_starter');
    $user->remove_role('thh_pro');
    $user->remove_role('thh_elite');
}

// === CART DISCOUNT ===
add_action('woocommerce_cart_calculate_fees', function($cart) {
    if (is_admin() && !defined('DOING_AJAX')) return;

    global $thh_tiers;
    $tier = thh_get_user_tier();
    if (!$tier) return;

    $discount_pct = $thh_tiers[$tier]['discount'];
    $membership_ids = [THH_STARTER_ID, THH_PRO_ID, THH_ELITE_ID];

    $cart_total = 0;
    foreach ($cart->get_cart() as $item) {
        if (in_array($item['product_id'], $membership_ids)) continue;
        $cart_total += $item['line_subtotal'];
    }

    if ($cart_total > 0) {
        $discount = round($cart_total * ($discount_pct / 100), 2);
        $label = sprintf('THH Club %s korting (%d%%)', ucfirst($tier), $discount_pct);
        $cart->add_fee($label, -$discount);
    }
});

// === FREE SHIPPING FOR PRO & ELITE ===
add_filter('woocommerce_package_rates', function($rates, $package) {
    $tier = thh_get_user_tier();
    if (!$tier || !in_array($tier, ['pro', 'elite'])) return $rates;

    foreach ($rates as $key => $rate) {
        if ($rate->method_id !== 'free_shipping') {
            $rates[$key]->cost = 0;
            $rates[$key]->label .= ' (Gratis - THH Club)';
        }
    }
    return $rates;
}, 100, 2);

// === ROLE ASSIGNMENT ON ORDER COMPLETE ===
add_action('woocommerce_order_status_completed', 'thh_process_membership_order');
add_action('woocommerce_order_status_processing', 'thh_process_membership_order');

function thh_process_membership_order($order_id) {
    $order = wc_get_order($order_id);
    if (!$order) return;
    $user_id = $order->get_customer_id();
    if (!$user_id) return;

    foreach ($order->get_items() as $item) {
        $tier = thh_get_tier_from_product($item->get_product_id());
        if ($tier) {
            thh_assign_membership_role($user_id, $tier);
            // Store subscription info in user meta
            update_user_meta($user_id, 'thh_membership_tier', $tier);
            update_user_meta($user_id, 'thh_membership_order_id', $order_id);
            update_user_meta($user_id, 'thh_membership_start', current_time('mysql'));
            break;
        }
    }
}

// === WPS SUBSCRIPTION STATUS HOOKS ===
add_action('wps_sfw_subscription_status_changed', function($sub_id, $new_status) {
    // Get user from subscription
    $user_id = get_post_meta($sub_id, 'wps_customer_id', true);
    if (!$user_id) {
        $parent = get_post_meta($sub_id, 'wps_parent_order', true);
        if ($parent) {
            $order = wc_get_order($parent);
            if ($order) $user_id = $order->get_customer_id();
        }
    }
    if (!$user_id) return;

    // Get product from subscription
    $pid = get_post_meta($sub_id, 'product_id', true);
    if (!$pid) $pid = get_post_meta($sub_id, 'wps_product_id', true);

    $tier = thh_get_tier_from_product($pid);
    if (!$tier) $tier = get_post_meta($pid, 'thh_membership_tier', true);
    if (!$tier) return;

    if (in_array($new_status, ['active', 'pending'])) {
        thh_assign_membership_role($user_id, $tier);
        update_user_meta($user_id, 'thh_membership_tier', $tier);
    } else {
        // cancelled, expired, on-hold
        thh_remove_membership_roles($user_id);
        delete_user_meta($user_id, 'thh_membership_tier');
    }
}, 10, 2);

// === MY ACCOUNT TAB ===
add_filter('woocommerce_account_menu_items', function($items) {
    $new = [];
    foreach ($items as $key => $label) {
        $new[$key] = $label;
        if ($key === 'orders') {
            $new['thh-membership'] = 'Mijn Lidmaatschap';
        }
    }
    return $new;
});

add_action('init', function() {
    add_rewrite_endpoint('thh-membership', EP_ROOT | EP_PAGES);
});

add_action('woocommerce_account_thh-membership_endpoint', function() {
    global $thh_tiers;
    $tier = thh_get_user_tier();
    $tier_names = ['starter' => 'Starter', 'pro' => 'Pro', 'elite' => 'Elite'];

    echo '<h2>Mijn THH Club Lidmaatschap</h2>';

    if ($tier) {
        $info = $thh_tiers[$tier];
        echo '<div style="background:#1B2A4A;color:#fff;padding:30px;border-radius:12px;margin-bottom:20px;">';
        echo '<h3 style="color:#D53949;margin-top:0;">🏆 ' . $tier_names[$tier] . ' Lid</h3>';
        echo '<p>✅ <strong>' . $info['discount'] . '% korting</strong> op alle producten</p>';
        if ($info['free_ship']) {
            echo '<p>✅ <strong>Gratis verzending</strong> op alle bestellingen</p>';
        }
        if ($tier === 'elite') {
            echo '<p>✅ <strong>VIP perks</strong> — early access & exclusieve deals</p>';
        }
        echo '</div>';

        if ($tier !== 'elite') {
            echo '<p><a href="/membership/" class="button" style="background:#D53949;color:#fff;border:0;padding:12px 24px;">Upgrade je lidmaatschap →</a></p>';
        }
    } else {
        echo '<p>Je bent nog geen lid van de THH Club.</p>';
        echo '<p><a href="/membership/" class="button" style="background:#D53949;color:#fff;border:0;padding:12px 24px;">Word lid →</a></p>';
    }
});

// === DISPLAY MEMBERSHIP BADGE ON CART ===
add_action('woocommerce_before_cart', function() {
    global $thh_tiers;
    $tier = thh_get_user_tier();
    if (!$tier) return;

    $info = $thh_tiers[$tier];
    $tier_names = ['starter' => 'Starter', 'pro' => 'Pro', 'elite' => 'Elite'];
    echo '<div style="background:#1B2A4A;color:#fff;padding:15px 20px;border-radius:8px;margin-bottom:20px;display:flex;align-items:center;gap:10px;">';
    echo '<span style="font-size:20px;">🏆</span>';
    echo '<span>Je bent <strong>THH Club ' . $tier_names[$tier] . '</strong> lid — ';
    echo '<strong>' . $info['discount'] . '% korting</strong> wordt automatisch toegepast!';
    if ($info['free_ship']) echo ' + <strong>Gratis verzending</strong>';
    echo '</span></div>';
});
